    var n = 0
    var m = 0
    var k = 0L

    fun main(args: Array<String>) {
        run()
    }

    fun run() {
        val sc = FastReader()
        n = sc.nextInt()
        m = sc.nextInt()
        k = sc.nextLong()
        solve()
    }

    fun solve() {
        var ansX = 0L
        var ansY = 0L
        if (k < n) {
            ansX = k + 1
            ansY = 1
        } else {
            k -= n
            val count = k / (m - 1)
            ansX = n - count
            if (count % 2 == 0) {
                ansY = 2 + (k % (m - 1))
            } else {
                ansY = m - (k % (m - 1))
            }
        }
        println("$ansX $ansY")
