                try {
                    st = StringTokenizer(br.readLine())
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            }
            return st!!.nextToken()
        }

        fun nextInt(): Int = next().toInt()
        fun nextLong(): Long = next().toLong()
        fun nextDouble(): Double = next().toDouble()
        fun nextLine(): String {
            var str = ""
            try {
                str = br.readLine()
            } catch (e: Exception) {
                e.printStackTrace()
            }
            return str
        }
    }
}

